    'diagnostics/stage3d/Stage3DProbe.as' = (Join-Path $PSScriptRoot 'diagnostics/stage3d/Stage3DProbe.as')
    'diagnostics/stage3d/BuildStage3DProbe.java' = (Join-Path $PSScriptRoot 'diagnostics/stage3d/BuildStage3DProbe.java')
    'diagnostics/stage3d/provenance.json' = (Join-Path $PSScriptRoot 'diagnostics/stage3d/provenance.json')
    'diagnostics/stage3d/Stage3DProbe.pak/launch.sh' = (Join-Path $PSScriptRoot 'diagnostics/stage3d/Stage3DProbe.pak/launch.sh')
    'CONTROLS.md' = (Join-Path $PSScriptRoot 'CONTROLS.md')
    'Build-Package.ps1' = $PSCommandPath
    'LICENSE' = $licensePath
}
foreach ($source in $entries.Values) {
    $item = Get-Item -LiteralPath $source
    if ($item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)) {
        throw "Package inputs must be ordinary source files: $source"
    }
}
$zip = [IO.Compression.ZipFile]::Open($zipPath, [IO.Compression.ZipArchiveMode]::Create)
try {
    foreach ($name in $entries.Keys) {
        [void][IO.Compression.ZipFileExtensions]::CreateEntryFromFile($zip, $entries[$name], $name)
    }
} finally { $zip.Dispose() }
$verify = [IO.Compression.ZipFile]::OpenRead($zipPath)
try {
    $actual = @($verify.Entries | ForEach-Object FullName | Sort-Object)
    $expectedNames = @($entries.Keys | Sort-Object)
    if (Compare-Object $expectedNames $actual) { throw 'Package content differs from the source allowlist.' }
    $manifest = @($verify.Entries | ForEach-Object {
        $stream = $_.Open()
        $hasher = [Security.Cryptography.SHA256]::Create()
        try { $hash = [BitConverter]::ToString($hasher.ComputeHash($stream)).Replace('-', '').ToLowerInvariant() }
        finally { $stream.Dispose(); $hasher.Dispose() }
        [pscustomobject]@{ file = $_.FullName; bytes = $_.Length; sha256 = $hash }
    })
} finally { $verify.Dispose() }
$manifest | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $output 'manifest.json')
Get-FileHash -LiteralPath $zipPath -Algorithm SHA256
Write-Output 'Source-only experimental package. A successful build does not establish game compatibility.'
